import React from "react";
import { useCart } from "../contexts/CartContext";

export default function ProductCard({ product }) {
  const { addToCart } = useCart();

  return (
    <div
      style={{
        padding: "12px",
        border: "1px solid #ddd",
        borderRadius: "10px",
        background: "#fff",
        transition: "0.2s",
      }}
      className="product-card"
    >
      <img
        src={product.imageUrl}
        alt={product.name}
        style={{
          width: "100%",
          height: "200px",
          objectFit: "cover",
          borderRadius: "8px",
          marginBottom: "10px",
        }}
      />

      <h3 style={{ margin: "6px 0", fontSize: "18px" }}>{product.name}</h3>

      <p
        style={{
          margin: "6px 0",
          fontSize: "14px",
          color: "#666",
          lineHeight: "1.4",
        }}
      >
        {product.description}
      </p>

      <p style={{ margin: "4px 0", fontWeight: "600", fontSize: "15px" }}>
        ₹{product.price}
      </p>

      <p style={{ margin: "4px 0", color: "#777", fontSize: "13px" }}>
        Category: {product.category}
      </p>

      <button
        onClick={() => addToCart(product)}
        style={{
          marginTop: "10px",
          padding: "8px",
          width: "100%",
          background: "#007bff",
          color: "#fff",
          borderRadius: "6px",
          border: "none",
          cursor: "pointer",
        }}
      >
        Add to Cart
      </button>
    </div>
  );
}
